class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = {
      phase: 'flush', vRoom: '۲', compostTemp: '19.6', roomTemp: '17.5', rh: '87', co2: '1200', airflow: 'خوب',
      hRoom: '۲', hFlush: '2', hWeight: '118', hWaste: '6', hGrade: 'درجه یک',
      dRoom: '۳', dLocation: 'ردیف ۴ شمالی', dSeverity: 'متوسط', dSymptoms: 'لکه‌های قهوه‌ای روی کلاهک، پراکنده',
      sCustomer: 'میدان مرکزی — غرفه ۱۲', sProduct: 'قارچ دکمه‌ای درجه یک',
      sWeight: '120', sUnitPrice: '185000', sPaid: '15000000'
    };
  }

  ranges() {
    return {
      spawn: { compost: [24, 26], room: [23, 26], rh: [92, 96], co2: [5000, 20000] },
      casing: { compost: [23, 26], room: [22, 25], rh: [93, 97], co2: [4000, 12000] },
      pinning: { compost: [18, 21], room: [16, 19], rh: [88, 93], co2: [800, 1500] },
      flush: { compost: [18, 21], room: [16, 19], rh: [85, 90], co2: [800, 1500] }
    };
  }

  num(n) {
    return Number(n).toLocaleString('fa-IR');
  }

  chip(value, range) {
    var n = parseFloat(value);
    var txt = 'مرجع ' + this.num(range[0]) + ' تا ' + this.num(range[1]);
    if (isNaN(n)) {
      return { text: txt, bg: '#F1EEE7', color: '#666158', ok: true };
    }
    var ok = n >= range[0] && n <= range[1];
    return {
      text: (ok ? 'در بازه' : 'خارج از بازه') + ' · ' + txt,
      bg: ok ? '#E3EEE1' : '#F5E9D6',
      color: ok ? '#166534' : '#8A5410',
      ok: ok
    };
  }

  set(key) {
    var self = this;
    return function (e) {
      var patch = {};
      patch[key] = e.target.value;
      self.setState(patch);
    };
  }

  renderVals() {
    var s = this.state;
    var r = this.ranges()[s.phase];

    var chips = {
      compost: this.chip(s.compostTemp, r.compost),
      room: this.chip(s.roomTemp, r.room),
      rh: this.chip(s.rh, r.rh),
      co2: this.chip(s.co2, r.co2)
    };

    var offList = [];
    if (!chips.compost.ok) { offList.push('دمای کمپوست'); }
    if (!chips.room.ok) { offList.push('دمای سالن'); }
    if (!chips.rh.ok) { offList.push('رطوبت'); }
    if (!chips.co2.ok) { offList.push('CO₂'); }

    var visit = offList.length === 0
      ? { text: 'همهٔ مقادیر در بازهٔ مرجع این مرحله‌اند — بازدید بدون هشدار ثبت می‌شود.', bg: '#E3EEE1', color: '#166534' }
      : { text: offList.length + ' مقدار خارج از بازه: ' + offList.join('، ') + '. سیستم یک هشدار باز می‌سازد و در گزارش «سالن‌ها و بیماری» نشان می‌دهد.', bg: '#F5E9D6', color: '#8A5410' };

    var w = parseFloat(s.hWeight) || 0;
    var waste = parseFloat(s.hWaste) || 0;
    var total = w + waste;
    var pct = total > 0 ? (waste / total) * 100 : 0;
    var hBg = '#E3EEE1', hColor = '#166534', hNote = 'سهم ضایعات در محدودهٔ عادی است.';
    if (pct > 10) {
      hBg = '#F5E1DF'; hColor = '#A32222';
      hNote = 'سهم ضایعات بالاست — سیستم پیشنهاد می‌کند مشاهدهٔ بیماری همان سالن ثبت شود.';
    } else if (pct > 5) {
      hBg = '#F5E9D6'; hColor = '#8A5410';
      hNote = 'سهم ضایعات کمی بالاتر از حد انتظار است؛ در گزارش تولید علامت می‌خورد.';
    }
    var harvest = {
      net: this.num(Math.round(w * 10) / 10),
      total: this.num(Math.round(total * 10) / 10),
      pct: this.num(Math.round(pct * 10) / 10),
      bg: hBg, color: hColor, note: hNote
    };

    var disease;
    if (s.dSeverity === 'کم') {
      disease = { bg: '#E3EEE1', pillBg: '#CFE3CC', color: '#166534', title: 'فقط ثبت و پایش',
                  action: 'ثبت مشاهده کافی است. سیستم در بازدید بعدی همان سالن، یادآوری پیگیری می‌سازد.' };
    } else if (s.dSeverity === 'شدید') {
      disease = { bg: '#F5E1DF', pillBg: '#EDCECB', color: '#A32222', title: 'اقدام فوری',
                  action: 'جداسازی ناحیه، ثبت فوری «اقدام درمانی/کنترل» و تخصیص وظیفه با اولویت فوری. تا ثبت نتیجه در «پایش پس از اقدام»، هشدار باز می‌ماند.' };
    } else {
      disease = { bg: '#F5E9D6', pillBg: '#EBDBC0', color: '#8A5410', title: 'اقدام در همان روز',
                  action: 'اقدام کنترلی همان روز انجام و در بخش «اقدام درمانی/کنترل» ثبت شود؛ سه روز بعد، فرم «پایش پس از اقدام» خودکار یادآوری می‌شود.' };
    }

    var sw = parseFloat(s.sWeight) || 0;
    var sp = parseFloat(s.sUnitPrice) || 0;
    var paid = parseFloat(s.sPaid) || 0;
    var gross = sw * sp;
    var receivable = gross - paid;
    var sale = {
      gross: this.num(Math.round(gross)),
      paid: this.num(Math.round(paid)),
      receivable: this.num(Math.round(receivable)),
      color: receivable > 0 ? '#A32222' : '#166534'
    };

    return {
      f: s,
      chips: chips,
      visit: visit,
      harvest: harvest,
      disease: disease,
      sale: sale,
      h: {
        phase: this.set('phase'), vRoom: this.set('vRoom'),
        compostTemp: this.set('compostTemp'), roomTemp: this.set('roomTemp'),
        rh: this.set('rh'), co2: this.set('co2'), airflow: this.set('airflow'),
        hRoom: this.set('hRoom'), hFlush: this.set('hFlush'), hWeight: this.set('hWeight'),
        hWaste: this.set('hWaste'), hGrade: this.set('hGrade'),
        dRoom: this.set('dRoom'), dLocation: this.set('dLocation'),
        dSeverity: this.set('dSeverity'), dSymptoms: this.set('dSymptoms'),
        sCustomer: this.set('sCustomer'), sProduct: this.set('sProduct'),
        sWeight: this.set('sWeight'), sUnitPrice: this.set('sUnitPrice'), sPaid: this.set('sPaid')
      }
    };
  }
}
